import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts
    opp_defects = 0
    my_defects = 0
    for me, op in history:
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    opp_coop_rate = (n - opp_defects) / n

    # Recent window analysis
    window = history[-12:] if n >= 12 else history
    wlen = len(window)
    recent_opp_d = 0
    recent_my_d = 0
    for me, op in window:
        if op == 'D':
            recent_opp_d += 1
        if me == 'D':
            recent_my_d += 1
    recent_opp_coop = (wlen - recent_opp_d) / wlen

    # Trailing streaks
    opp_d_streak = 0
    for me, op in reversed(history):
        if op == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for me, op in reversed(history):
        if me == 'D':
            my_d_streak += 1
        else:
            break

    last_me, last_op = history[-1]

    # --- Pure/near-pure defector: lock in mutual defection ---
    if opp_defects == n or (n >= 6 and recent_opp_d == wlen and opp_coop_rate < 0.1):
        return 'D'

    # --- Very cooperative opponent ---
    # Exploit just enough to boost payoff without triggering retaliation.
    if opp_coop_rate >= 0.95 and recent_opp_d == 0:
        # Defect rarely, and never two rounds in a row (avoid provoking punishment).
        if n >= 4 and last_me == 'D':
            return 'C'
        if n >= 20 and opp_d_streak == 0 and rng.random() < 0.12:
            return 'D'
        return 'C'

    if opp_coop_rate >= 0.8 and recent_opp_d <= 1:
        # Occasional probing exploit, but return to C afterwards.
        if last_me == 'D':
            return 'C'
        if n >= 25 and rng.random() < 0.09:
            return 'D'
        return 'C'

    # --- Highly defective opponent (not pure) ---
    if recent_opp_coop <= 0.2 and recent_opp_d >= 4:
        # Mostly stay in D, occasionally probe for a recovery.
        if opp_d_streak >= 3 and rng.random() < 0.07:
            return 'C'
        return 'D'

    if opp_coop_rate < 0.25:
        # Chronic defector: defect, punish quickly.
        if last_op == 'D':
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # --- Mutually locked in defection: try to break the cycle ---
    if opp_d_streak >= 3 and my_d_streak >= 3:
        # Two cooperative probes to invite reciprocal cooperation.
        if my_d_streak <= 4:
            return 'C'
        return 'D'

    # --- Last round exploit (cooperator detected) ---
    if n >= 96 and opp_coop_rate >= 0.65:
        return 'D'

    # --- Endgame: tighten patience, exploit recognized cooperators ---
    if n >= 88 and opp_coop_rate >= 0.75 and recent_opp_d <= 1:
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # --- Responsive core: generous tit-for-tat with recovery ---
    if last_op == 'D':
        # Opponent just defected
        if recent_opp_d == 1 and opp_coop_rate > 0.6 and n >= 8:
            # Isolated defection against a generally cooperative opponent: forgive often.
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        if opp_coop_rate > 0.5 and recent_opp_d <= 2:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        # Otherwise retaliate.
        return 'D'

    # Opponent just cooperated.
    # Reward: cooperate back, but occasionally exploit clearly weak opponents.
    if recent_opp_coop >= 0.75 and opp_coop_rate >= 0.6:
        # Only exploit when not already defecting recently to keep relation stable.
        if my_d_streak == 0 and n >= 15 and rng.random() < 0.07:
            return 'D'
        return 'C'

    if recent_opp_coop >= 0.5:
        if my_d_streak >= 1:
            return 'C'
        return 'C'

    # Mixed/uncertain: cooperate, but keep some defensive pressure.
    if recent_my_d >= 2:
        return 'C'
    if rng.random() < 0.7:
        return 'C'
    return 'D'
